const refreshChargePaid = `-- name: RefreshChargePaid :one
UPDATE charges c
SET paid_kop = x.paid,
    status = CASE WHEN c.status = 'cancelled' THEN 'cancelled'
                  WHEN x.paid >= c.amount_kop THEN 'paid'
                  WHEN x.paid = 0 THEN 'open'
                  ELSE 'partially_paid' END
FROM (SELECT COALESCE(sum(amount_kop), 0)::bigint AS paid FROM payment_allocations
      WHERE charge_id = $1 AND reversed_at IS NULL) x
WHERE c.id = $1
RETURNING c.id, c.contract_id, c.kind, c.title, c.period_month, c.period_start, c.period_end, c.due_date, c.amount_kop, c.original_amount_kop, c.paid_kop, c.status, c.penalty_state, c.source_charge_id, c.calc_details, c.origin, c.idempotency_key, c.created_by, c.cancelled_at, c.cancelled_by, c.cancel_reason, c.created_at, c.updated_at
`

// paid_kop = сумма активных распределений; статус по оплате (у отменённого не меняется).
func (q *Queries) RefreshChargePaid(ctx context.Context, id uuid.UUID) (Charge, error) {
	row := q.db.QueryRow(ctx, refreshChargePaid, id)
	var i Charge
	err := row.Scan(
		&i.ID,
		&i.ContractID,
		&i.Kind,
		&i.Title,
		&i.PeriodMonth,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.DueDate,
		&i.AmountKop,
		&i.OriginalAmountKop,
		&i.PaidKop,
		&i.Status,
		&i.PenaltyState,
		&i.SourceChargeID,
		&i.CalcDetails,
		&i.Origin,
		&i.IdempotencyKey,
		&i.CreatedBy,
		&i.CancelledAt,
		&i.CancelledBy,
		&i.CancelReason,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

